SELECT p.id AS position_id, 'ENTRY' AS role, s.id AS signal_id, s.symbol, s.interval_code, s.candle_open_time, s.decision, s.original_decision, s.total_score, s.confidence_score, s.effective_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.selected_strategy, s.market_regime, s.confirmed_regime, s.entry_authority, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, s.atr_entry_type, s.atr_overextended, s.confluence_status, s.confluence_higher_interval, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_correlation, s.liquidity_status, s.derivatives_status, s.generated_at, s.created_at FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id WHERE p.id IN (182,172,162,158,143,137)
UNION ALL
SELECT p.id, 'EXIT', s.id, s.symbol, s.interval_code, s.candle_open_time, s.decision, s.original_decision, s.total_score, s.confidence_score, s.effective_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.selected_strategy, s.market_regime, s.confirmed_regime, s.entry_authority, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, s.atr_entry_type, s.atr_overextended, s.confluence_status, s.confluence_higher_interval, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_correlation, s.liquidity_status, s.derivatives_status, s.generated_at, s.created_at FROM paper_position p JOIN trade_signal s ON s.id = p.exit_signal_id WHERE p.id IN (182,172,162,158,143,137)
ORDER BY 1, 2